-- GENERATED by `wfj generate` from data/gossip/gossip-22.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["22031047e11710e0"] = { "È giunto il momento, <fratello/sorella> <mio/mia> d'armi, di strappare la notte al Flagello!", "." },
  ["220f936943e19a5e"] = { "Ben fatto, giovane <ladro/ladra>. Ben fatto davvero....", "." },
  ["2213664152c6b268"] = { "Okothos ti addestrerà, {name}.", "." },
  ["2213d6446a5f348a"] = { "Oh, sei tornat<o/a>, {name}! Hai il samophlange?", "." },
  ["221732b87fd9d720"] = { "Guse? Jeztor? Sono... in avvitamento?? Mari di ⟦Southshore=Riva del Sud⟧??", "." },
  ["22202e910ce155eb"] = { "Pover'uomo, questo spiega tante cose.", "." },
  ["2220363f7f4c4b87"] = { "%s strizza l'occhio a {name} con aria d'intesa.", "." },
  ["22225356bdac8333"] = { "Stai parlando con l'orco sbagliato. Io non addestro i novizi. Parla con il giovane Whuut, laggiù... e usa parole semplici.", "." },
  ["22327c8140ad6b95"] = { "Ricorda: se molesti il rappresentante o intasi il canale, il tuo account potrebbe essere espulso, bannato o peggio.", "." },
  ["22378cd28b2e8092"] = { "Piacere di conoscerti, {class}. Mi chiamo Roetten. Sono a capo della Reclaimers Incorporated.\n\nIo e la mia gilda ci specializziamo nel recupero di beni perduti. Di solito assumiamo avventurieri coraggiosi e li mandiamo a portare a termine incarichi per conto di chi non è in grado di farlo o non ne ha il tempo.", "." },
  ["2237e6bdb2f8f54d"] = { "Grazie, {name}. Ora andiamocene da qui!", "." },
  ["2248dbd6eebc7312"] = { "Se riesco a procurarmi gli ingredienti giusti, possiamo creare degli esplosivi che non solo mi permetteranno di danneggiare le attività della S.P.R. & Co., ma creeranno anche un diversivo.\n\nSo che ti ho fatto colpo, ma il bello deve ancora venire... Presto ti dirò di più.", "." },
  ["225312a647bfb1a1"] = { "Anch'io avrei bisogno di bere qualcosa e riposare. La troverai proprio nell'angolo nord-occidentale di ⟦Razor Hill=Tranciacolle⟧. Saluta da parte mia il locandiere Grosk.", "." },
  ["2253a57280bff35d"] = { "Hahaha, tue guardie niente contro Flagello!", "." },
  ["225446e72ade1edb"] = { "Che posso fare per te, {name}?", "." },
  ["2255615801ce3085"] = { "Sono nel bel mezzo di un compito molto importante. Affari da cercatore. A meno che tu non abbia qualcosa di altrettanto importante da dire, e ne dubito, dovrai scusarmi.", "." },
  ["225e6b022042c26e"] = { "Bevi questo, ti aiuterà.", "." },
  ["2295bc9de950873f"] = { "Lasciami andare e basta! Ne ho abbastanza!", "." },
  ["229748cadbd561d4"] = { "La tua anima ora è legata a me!", "." },
  ["22a16fd9f19b7368"] = { "Maraudon si trova a metà della costa occidentale di ⟦Desolace=Desolanda⟧, nella ⟦Valley of Spears=Valle delle Lance⟧.", "." },
  ["22a61e0cc8912901"] = { "Uno degli alti elfi che parla con me... a ⟦Thunder Bluff=Picco del Tuono⟧. Le meraviglie non finiranno mai?\n\nEbbene, <plasmatore/plasmatrice> del vento, lascia che mi unisca ai fratelli e alle sorelle del Circolo della Terra nel darti il benvenuto su Azeroth. I miei compagni druidi del ⟦Cenarion Circle=Circolo Cenariano⟧ hanno molta saggezza da trasmetterti, <figlio/figlia> della natura.", "." },
  ["22aee4c24720b7f6"] = { "Shì, è vero, non ci vedo, proprio come una talpa! E ho bevuto come una... ehm, come una cosha che beve un shacco.\n\nTi dico una cosha, {race}. È il bere che mi tiene i shenshi affilati. Lo shanno tutti che quando perdi un shenso, gli altri shenshi diventano più attenti. Il mio shenso della shbornia di queshti tempi è incredibile.", "." },
  ["22b0be5f0ebc5b24"] = { "Non dimenticare di fare scorta di carta da regalo per queste feste! Niente dice \"meraviglioso Grande Inverno\" come armature e armi incartate per i tuoi amici e la tua famiglia.", "." },
  ["22b18bf91b57c0ec"] = { "Io ⟦Grimlok=Tetrok⟧, re!", "." },
  ["22b1e0eed87f2c39"] = { "Ish nu! Basta così!", "." },
  ["22b31c6e90f9f0b9"] = { "Ora tocca a me sentirmi un po' grezzo; sinceramente non credo di avere altro da insegnarti. Ma sai chi può farlo? ⟦Bengus Deepforge=Bengus Forgiafonda⟧ a ⟦Ironforge=Forgiardente⟧: quello sì che è un nano che conosce il suo acciaio. Va' a cercarlo nella ⟦Great Forge=Grande Forgia⟧ di ⟦Ironforge=Forgiardente⟧, e vedi se è disposto a prendere sotto di sé un nuovo apprendista.", "." },
  ["22b4b923d5cb85a1"] = { "Ce l'abbiamo fatta, <ragazzo/ragazza>! L'⟦Alliance=Alleanza⟧ e l'⟦Horde=Orda⟧ hanno finito di raccogliere tutto ciò che pensiamo ci servirà per la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. In questo momento le ultime merci vengono portate alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e arriveranno tutte entro $2113w giorni. Dopodiché, <un/una> <eroe/eroina> <coraggioso/coraggiosa> dovrà suonare lo Scarab Gong con lo Scepter of the Shifting Sands per aprire i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Quando quei cancelli si apriranno, la guerra avrà inizio!", "." },
  ["22b5d6c11828c714"] = { "Cosa ti ha portato al Circolo della Terra?", "." },
  ["22b67b17851ec7c7"] = { "Abbiamo fame di vendetta.", "." },
  ["22c0cffb3350b748"] = { "%s scuote la testa con delusione.", "." },
  ["22c7db75d4734b0a"] = { "Il tuo travestimento non mi inganna, tentatrice. È giunta la tua ora.", "." },
  ["22c8c3a1223a4cf0"] = { "Ti prego, abbi pietà di me! Ho informazioni che vanno oltre i confini dell'alleanza. Non sono certo un simpatizzante dell'⟦Horde=Orda⟧, ma è in corso un tradimento politico che deve essere svelato!", "." },
  ["22caaa705eca4eaa"] = { "Silenzio, servo! Avrò la mia vendetta! Morte a ⟦Stormwind=Roccavento⟧! Morte per pollo!", "." },
  ["22e176cf0c106888"] = { "Prendete una corda!", "." },
  ["22e899d1750412b6"] = { "Ehi, salve, signore mie. Avete sentito della nuova piaga?", "." },
  ["22e92603ceeba523"] = { "Ho perso il mio ⟦Kris of Unspoken Names=Kris dei Nomi Innominati⟧. Puoi sostituirmelo?", "." },
  ["22eac5b1bebdcc1f"] = { "%s tende la mano verso il capitano Beltis mentre cade.", "." },
  ["22ec6aa982b70229"] = { "Vieni ad apprendere le vie del cacciatore. Orgoglio, onore e tradizione.", "." },
  ["22f96e24b22ec4a9"] = { "«...»\n\nIl corpo del druido tauren giace immobile. Sembra che sia finalmente passato da questo mondo al grande aldilà che gli era stato promesso.", "." },
  ["22fdf4a34c7de687"] = { "La Bandiera dell'⟦Horde=Orda⟧ è stata presa da {name}!", "." },
  ["22ff6d7eacc8cfb0"] = { "Ho mostrato a Cog l'inizio della nostra macchina per osservare le stelle. Ne è rimasto colpito. Hai per caso trovato qualcosa che rifletta la luce?", "." },
})
